text(await tools.apply_patch("*** Begin Patch
*** Add File: /home/diogenes/Projects/apps/twyne/convex/instrumentTasks.ts
+import { makeFunctionReference } from "convex/server";
+import { ConvexError, v } from "convex/values";
+import { mutation, query, internalMutation, internalQuery, type QueryCtx } from "./_generated/server";
+import type { Doc, Id } from "./_generated/dataModel";
+import { taskDocument, taskKind, sourceRef, taskResult, feedback, failureKind } from "./instrumentTaskValidators";
+import { instrumentTextFingerprint, instrumentTaskCanCancel } from "../src/utils/instrument-tasks-model";
+
+export const INSTRUMENT_LEASE_MS = 180_000;
+export const INSTRUMENT_MAX_CLAIMS = 3;
+const runRef = makeFunctionReference<"action", { taskId: Id<"instrumentTasks"> }, null>("instrumentTasksRunner:run");
+const expireRef = makeFunctionReference<"mutation", { taskId: Id<"instrumentTasks">; leaseToken: string }, null>("instrumentTasks:expireLease");
+const publicTask = taskDocument.omit("userId", "productSubject", "did", "sessionVersion", "leaseToken", "leaseExpiresAt", "scheduledId");
+function view(row: Doc<"instrumentTasks">) {
+  const { userId, productSubject, did, sessionVersion, leaseToken, leaseExpiresAt, scheduledId, ...task } = row;
+  return task;
+}
+async function identity(ctx: QueryCtx) {
+  const value = await ctx.auth.getUserIdentity();
+  if (!value) throw new ConvexError("Sign in with Not Organic to queue durable tasks.");
+  return value;
+}
+async function folioExists(ctx: QueryCtx, userId: string, folioId: string) {
+  const entry = await ctx.db.query("folioEntries").withIndex("by_userId_itemId", q => q.eq("userId", userId).eq("itemId", folioId)).unique();
+  return !!entry;
+}
+async function permitted(ctx: QueryCtx, task: Doc<"instrumentTasks">) {
+  const deleting = await ctx.db.query("accountDeletionJobs").withIndex("by_ownerId", q => q.eq("ownerId", task.userId)).unique();
+  if (deleting || !(await folioExists(ctx, task.userId, task.folioId))) return false;
+  const link = await ctx.db.query("providerIdentities").withIndex("by_productSubject", q => q.eq("productSubject", task.productSubject)).unique();
+  return link?.verificationMethod === "notorganic_pkce" && link.did === task.did && link.sessionVersion === task.sessionVersion;
+}
+async function owned(ctx: QueryCtx, taskId: Id<"instrumentTasks">) {
+  const caller = await identity(ctx);
+  const row = await ctx.db.get("instrumentTasks", taskId);
+  if (!row || row.userId !== caller.tokenIdentifier) throw new ConvexError("Task not found.");
+  return row;
+}
+function bound(value: string, min: number, max: number, label: string) {
+  if (value.trim().length < min || value.length > max) throw new ConvexError(`${label} must contain ${min}–${max} characters.`);
+}
+
+export const queue = mutation({
+  args: { requestId: v.string(), folioId: v.string(), kind: taskKind, instruction: v.string(), selectedText: v.string(), sources: v.array(sourceRef) },
+  returns: v.id("instrumentTasks"),
+  handler: async (ctx, args) => {
+    const caller = await identity(ctx);
+    bound(args.requestId, 1, 128, "Request id");
+    bound(args.folioId, 1, 256, "Folio id");
+    bound(args.instruction, 1, 2000, "Task instruction");
+    bound(args.selectedText, 1, 20_000, "Selected text");
+    if (args.sources.length > 3 || (args.kind === "source-research" && !args.sources.length)) throw new ConvexError("Choose one to three account resources for source research.");
+    const seen = new Set<string>();
+    for (const ref of args.sources) {
+      bound(ref.sourceId, 1, 256, "Source id"); bound(ref.uri, 1, 4096, "Resource URI"); bound(ref.label, 1, 200, "Resource label");
+      const key = JSON.stringify([ref.sourceId, ref.uri]);
+      if (seen.has(key)) throw new ConvexError("Choose each resource once.");
+      seen.add(key);
+    }
+    const previous = await ctx.db.query("instrumentTasks").withIndex("by_userId_and_requestId", q => q.eq("userId", caller.tokenIdentifier).eq("requestId", args.requestId)).unique();
+    if (previous) {
+      if (previous.folioId !== args.folioId || previous.kind !== args.kind || previous.instruction !== args.instruction || previous.selectedText !== args.selectedText || JSON.stringify(previous.sources) !== JSON.stringify(args.sources)) throw new ConvexError("This request id belongs to a different task.");
+      return previous._id;
+    }
+    if (!(await folioExists(ctx, caller.tokenIdentifier, args.folioId))) throw new ConvexError("Sync this folio to your account before queueing a task.");
+    if (await ctx.db.query("accountDeletionJobs").withIndex("by_ownerId", q => q.eq("ownerId", caller.tokenIdentifier)).unique()) throw new ConvexError("Account deletion is in progress.");
+    const productSubject = caller.subject || caller.tokenIdentifier;
+    const link = await ctx.db.query("providerIdentities").withIndex("by_productSubject", q => q.eq("productSubject", productSubject)).unique();
+    if (link?.verificationMethod !== "notorganic_pkce") throw new ConvexError("Reconnect your Not Organic account before queueing durable tasks.");
+    const now = Date.now();
+    const taskId = await ctx.db.insert("instrumentTasks", { ...args, userId: caller.tokenIdentifier, productSubject, did: link.did, sessionVersion: link.sessionVersion, fingerprint: instrumentTextFingerprint(args.selectedText), status: "queued", attempts: 0, createdAt: now, updatedAt: now });
+    const scheduledId = await ctx.scheduler.runAfter(0, runRef, { taskId });
+    await ctx.db.patch("instrumentTasks", taskId, { scheduledId });
+    return taskId;
+  },
+});
+export const list = query({
+  args: { folioId: v.string() }, returns: v.array(publicTask),
+  handler: async (ctx, { folioId }) => {
+    const caller = await identity(ctx);
+    const rows = await ctx.db.query("instrumentTasks").withIndex("by_userId_and_folioId", q => q.eq("userId", caller.tokenIdentifier).eq("folioId", folioId)).order("desc").take(50);
+    return rows.map(view);
+  },
