    if (!(await folioExists(ctx, caller.tokenIdentifier, args.folioId))) throw new ConvexError("Sync this folio to your account before queueing a task.");
    if (await ctx.db.query("accountDeletionJobs").withIndex("by_ownerId", q => q.eq("ownerId", caller.tokenIdentifier)).unique()) throw new ConvexError("Account deletion is in progress.");
    const productSubject = caller.subject || caller.tokenIdentifier;
    const link = await ctx.db.query("providerIdentities").withIndex("by_productSubject", q => q.eq("productSubject", productSubject)).unique();
    if (link?.verificationMethod !== "notorganic_pkce") throw new ConvexError("Reconnect your Not Organic account before queueing durable tasks.");
    const now = Date.now();
    const taskId = await ctx.db.insert("instrumentTasks", { ...args, userId: caller.tokenIdentifier, productSubject, did: link.did, sessionVersion: link.sessionVersion, fingerprint: instrumentTextFingerprint(args.selectedText), status: "queued", attempts: 0, createdAt: now, updatedAt: now });
