      typeof error === "string"
        ? inferCodeFromMessage(error, options.source ?? "unknown")
        : "INTERNAL_ERROR",
      {
        ...options,
        source: options.source ?? "unknown",
        validationKey:
          options.validationKey ??
          (typeof error === "string"
