function recoveryActionFrom(
  value: unknown,
): AppErrorRecovery["action"] | undefined {
  switch (normalizedTag(value)) {
    case "RETRY":
    case "RELOAD":
      return "retry";
    case "RETRY_LATER":
      return "retry-later";
    case "SIGN_IN":
      return "sign-in";
    case "OPEN_SETTINGS":
      return "check-configuration";
    case "USE_FORM":
      return "fix-input";
    case "CHOOSE_PROVIDER":
      return "choose-provider";
    case "CONTACT_SUPPORT":
      return "contact-support";
    case "NONE":
      return "none";
    default:
      return undefined;
  }
