  constructor(
    message: string,
    public readonly retryAfterMs: number,
  ) {
    super(message);
    this.name = "RateLimitError";
  }
}

interface ConsumeArgs {
  action: string;
  identifier: string;
  limit: number;
  windowMs: number;
}

/**
