/**
 * TypeSafe "System One" (Jev) — typed questions and answers.
 *
 * Jev does not generate text. It answers a fixed set of questions about some
 * state, and returns a calibrated probability distribution for each one. That
 * is the whole surface: three question kinds, three answer shapes.
 *
 *   Noul    probability of yes, 0..1
 *   Choice  pick one option, plus the probability of every option
 *   Score   ordered levels, returning a probability-weighted value
 *
 * This module is transport-free on purpose. It builds requests and reads
 * answers; `convex/systemOne.ts` is the only place that holds the API key and
 * talks to the network, because the key must never reach the browser bundle.
 *
 * Costs, measured against the live API rather than quoted from the docs: the
 * full 11-criterion rubric spine batched into one request took 378 ms and
 * 1,401 input tokens — $0.0000588, or roughly 17,000 rubric passes per dollar.
 * Output tokens are free. This is cheap enough to run on a typing pause.
 */

/* ── Questions ─────────────────────────────────────────────────── */

/** Probability that the answer is yes. */
export interface NoulQuestion {
  type: "noul";
  instructions: string;
}

/** Pick exactly one of `criteria`. */
export interface ChoiceQuestion {
  type: "choice";
  instructions: string;
  criteria: string[];
}

/**
 * Ordered levels, worst first. The answer is a probability-weighted value
 * across them, so it can land between two levels.
 */
export interface ScoreQuestion {
  type: "score";
  instructions: string;
  criteria: string[];
}

export type SystemOneQuestion = NoulQuestion | ChoiceQuestion | ScoreQuestion;

/**
 * One request. Independent questions over the same `state` run in parallel
 * and barely change latency, so batch aggressively — but they cannot see each
 * other's answers. A second round-trip is only justified when an answer is
 * needed to *fetch* new evidence.
 *
 * Budget: 64k context per request, of which 32k is for `state`.
 */
export interface SystemOneRequest {
  model?: string;
  state: Record<string, unknown>;
  questions: Record<string, SystemOneQuestion>;
}

/* ── Answers ───────────────────────────────────────────────────── */

export interface NoulAnswer {
  type: "noul";
  /** 0 (no) to 1 (yes). */
  noul: number;
}

export interface ChoiceAnswer {
  type: "choice";
  /** The highest-probability option. */
  choice: string;
  /** Every option mapped to its probability; sums to 1. */
  probabilities: Record<string, number>;
  confidence: number;
}

export interface ScoreAnswer {
  type: "score";
  /** Probability-weighted across levels; can land between them. */
  score: number;
  /** Level index (as a string key) back to its description. */
  legend: Record<string, string>;
  /** Level index to probability; sums to 1. */
  probabilities: Record<string, number>;
  confidence: number;
}

export type SystemOneAnswer = NoulAnswer | ChoiceAnswer | ScoreAnswer;

export interface SystemOneUsage {
  input_tokens: number;
  output_tokens: number;
}

export interface SystemOneResponse {
  model: string;
  answers: Record<string, SystemOneAnswer>;
  usage: SystemOneUsage;
}

/** Input tokens only — output is not billed. */
export const USD_PER_INPUT_TOKEN = 0.042 / 1_000_000;

export function estimateCost(usage: SystemOneUsage): number {
  return usage.input_tokens * USD_PER_INPUT_TOKEN;
}

/* ── Builders ──────────────────────────────────────────────────── */

export function noul(instructions: string): NoulQuestion {
  return { type: "noul", instructions };
}

export function choice(
  instructions: string,
  criteria: string[],
): ChoiceQuestion {
  return { type: "choice", instructions, criteria };
}

/** `criteria` must be ordered worst-to-best; the index is the level. */
export function score(instructions: string, criteria: string[]): ScoreQuestion {
  return { type: "score", instructions, criteria };
}

/* ── Reading answers ───────────────────────────────────────────── */

export function isNoul(a: SystemOneAnswer | undefined): a is NoulAnswer {
  return a?.type === "noul";
}

export function isChoice(a: SystemOneAnswer | undefined): a is ChoiceAnswer {
  return a?.type === "choice";
}

export function isScore(a: SystemOneAnswer | undefined): a is ScoreAnswer {
  return a?.type === "score";
}

/**
 * Whether a Score's distribution is bimodal — mass at both ends with a trough
 * in the middle, which is exactly where the weighted mean lands.
 *
 * This is not hypothetical. A measured answer came back `score: 1.43`,
 * `confidence: 0.14`, `probabilities: {0: 0.21, 1: 0.16, 2: 0.63}`: the scalar
 * points at the level the model assigned the *least* mass to. Any threshold on
 * the scalar alone would have been wrong. Callers below their confidence floor
 * should branch on the distribution or decline to show a grade at all.
 */
export function isBimodal(answer: ScoreAnswer): boolean {
  const levels = Object.keys(answer.probabilities)
    .map(Number)
    .sort((a, b) => a - b);
  if (levels.length < 3) return false;

  const nearest = Math.round(answer.score);
  const pAtMean = answer.probabilities[String(nearest)] ?? 0;
  const peak = Math.max(...Object.values(answer.probabilities));

  // The mean sits in a trough: some level is at least twice as likely as the
  // one the mean actually names.
  return peak > pAtMean * 2;
}

/**
 * The level the model gave the most mass to, which is not always the level
 * nearest `score`. Use this when `isBimodal` is true and you still must pick.
 */
export function modalLevel(answer: ScoreAnswer): number {
  let best = 0;
  let bestP = -1;
  for (const [level, p] of Object.entries(answer.probabilities)) {
    if (p > bestP) {
      bestP = p;
      best = Number(level);
    }
  }
  return best;
}

/**
 * Rescale a Score onto 0..max (Twyne's rubric is 0–10) using the number of
 * levels the question declared, not a hardcoded assumption.
 */
export function scoreOutOf(answer: ScoreAnswer, max: number): number {
  const levels = Object.keys(answer.legend).length;
  if (levels < 2) return 0;
  return (answer.score / (levels - 1)) * max;
}

/* ── Confidence semantics ──────────────────────────────────────── */

/**
 * What `confidence` does and does not mean, kept here so call sites cannot
 * quietly reinvent it:
 *
 * - For a Noul there is no confidence field at all. A Noul near 0.5 means
 *   *equally likely yes or no* — it does not mean "medium intensity". Reading
 *   a Noul as a magnitude is the most common way to misuse this API.
 * - For Choice and Score, confidence measures how concentrated the probability
 *   distribution is. It is **not** a correctness estimate and **not**
 *   permission to act. Low confidence often just means several answers are
 *   equally fine.
 *
 * Empirically this tracks objectivity, which is the useful part: on a
 * deliberately bad draft, `integrity` scored 0.01 at confidence 0.99 while the
 * genuinely subjective `targetFit` scored 2.38 at confidence 0.43. That makes
 * confidence a good trigger for escalating to a frontier model, and a bad
 * trigger for taking an action on the user's behalf.
 */
export function confidenceOf(answer: SystemOneAnswer): number | null {
  return isNoul(answer) ? null : answer.confidence;
}
import type { Node as PmNode } from "@tiptap/pm/model";
import type {
  Occurrence,
  SectionInfo,
  Finding,
  LensId,
} from "../living-desk-contract";

export interface Block {
  kind: "paragraph" | "heading" | "quote" | "code" | "other";
  text: string;
  pos: number;
  paragraph: number;
  section: number;
  /** Text runs retain document gaps occupied by inline atoms. */
  runs?: { offset: number; length: number; pos: number }[];
}
export interface Segments {
  blocks: Block[];
  sections: SectionInfo[];
  plainText: string;
}

export function posAtOffset(block: Block, offset: number, end = false): number {
  const runs = block.runs;
  if (!runs?.length) return block.pos + offset;
  // At a text/atom boundary, starts belong to the next text and ends to the preceding text.
  const run = runs.find(
    (r) =>
      offset >= r.offset &&
      (end ? offset <= r.offset + r.length : offset < r.offset + r.length),
  );
  if (run) return run.pos + offset - run.offset;
  const last = runs[runs.length - 1];
  return last.pos + last.length;
}

export function segmentDocument(doc: PmNode): Segments {
  const blocks: Block[] = [];
  const sections: SectionInfo[] = [];
  let paragraph = 0;
  doc.descendants((node, pos) => {
    if (!node.isTextblock) return;
    const quote = Array.from(
      { length: doc.resolve(pos).depth + 1 },
      (_, i) => doc.resolve(pos).node(i).type.name,
    ).includes("blockquote");
    const kind: Block["kind"] = quote
      ? "quote"
      : node.type.name === "codeBlock"
        ? "code"
        : node.type.name === "heading"
          ? "heading"
          : node.type.name === "paragraph"
            ? "paragraph"
            : "other";
    if (!sections.length || kind === "heading") {
      if (sections.length) sections[sections.length - 1].to = pos;
      sections.push({
        index: sections.length,
        title: kind === "heading" ? node.textContent : "Opening",
        from: pos + 1,
        to: doc.content.size,
        words: 0,
      });
    }
    let text = "";
    const runs: NonNullable<Block["runs"]> = [];
    node.descendants((child, offset) => {
      if (child.isText) {
        runs.push({
          offset: text.length,
          length: child.text!.length,
          pos: pos + 1 + offset,
        });
        text += child.text;
      }
    });
    const section = sections.length - 1;
    if (kind !== "heading") paragraph++;
    blocks.push({
      kind,
      text,
      pos: pos + 1,
      paragraph: Math.max(1, paragraph),
      section,
      runs,
    });
    sections[section].words += text.trim().split(/\s+/).filter(Boolean).length;
    return false;
  });
  return {
    blocks,
    sections,
    plainText: blocks.map((b) => b.text).join("\n\n"),
  };
}

export function occurrence(
  block: Block,
  offset: number,
  length: number,
  id: string,
  extra: Partial<Occurrence> = {},
): Occurrence {
  const contextStart = Math.max(0, offset - 55);
  const contextEnd = Math.min(block.text.length, offset + length + 55);
  let before = block.text.slice(contextStart, offset);
  let after = block.text.slice(offset + length, contextEnd);
  if (contextStart > 0 && /\S/.test(block.text[contextStart - 1]))
    before = before.replace(/^\S*\s/, "");
  if (contextEnd < block.text.length && /\S/.test(block.text[contextEnd]))
    after = after.replace(/\s\S*$/, "");
  return {
    id: `${id}:${posAtOffset(block, offset)}`,
    from: posAtOffset(block, offset),
    to: posAtOffset(block, offset + length, true),
    text: block.text.slice(offset, offset + length),
    before: before.trimStart(),
    after: after.trimEnd(),
    section: block.section,
    paragraph: block.paragraph,
    provenance: "rule",
    flagged: true,
    ...extra,
  };
}

export function finding(
  id: string,
  lens: LensId,
  title: string,
  metric: string,
  occurrences: Occurrence[],
): Finding {
  const count = occurrences.filter((o) => o.flagged).length;
  return {
    id,
    lens,
    title,
    metric,
    level: "piece",
    criterion: "consistency",
    count,
    effort: count,
    impact: null,
    state: count ? "open" : "resolved",
    occurrences: [...occurrences].sort(
      (a, b) => Number(b.flagged) - Number(a.flagged),
    ),
    actions: ["fix-one", "fix-all", "deliberate", "jump"],
    provenance: occurrences.some((o) => o.provenance === "jev")
      ? "jev"
      : "rule",
  };
}

export function matchCase(original: string, replacement: string): string {
  if (/[A-Z]/.test(original) && original === original.toUpperCase())
    return replacement.toUpperCase();
  return /^[A-Z]/.test(original)
    ? replacement[0].toUpperCase() + replacement.slice(1)
    : replacement;
}
import { scoreStaticFeatures } from "../rubric";
import type { RubricResult } from "../../types";
import type {
  Finding,
  LiveScore,
  ScoreCriterion,
} from "../living-desk-contract";

// rubric.ts keeps FEATURE_WEIGHTS private. Mirror its six relevant weights;
// consistency takes the omitted length weight, equal to vocabulary.
export const RULE_WEIGHTS: Record<string, number> = {
  evidence: 0.2,
  pacing: 0.15,
  vocabulary: 0.1,
  integrity: 0.2,
  paragraphShape: 0.1,
  structure: 0.15,
  consistency: 0.1,
};
const LABELS: Record<string, string> = {
  evidence: "Evidence & Support",
  pacing: "Pacing & Rhythm",
  vocabulary: "Vocabulary & Diction",
  integrity: "Bullshit Resistance",
  paragraphShape: "Paragraph Shape",
  structure: "Organization & Flow",
  consistency: "Consistency",
};
export interface Confirmation {
  review: RubricResult;
  at: number;
  rules: Record<string, number>;
}
export const clampScore = (n: number) => Math.max(0, Math.min(10, n));
export function consistencyPenalty(findings: Finding[]): number {
  return Math.min(
    6,
    findings.reduce(
      (sum, f) =>
        sum +
        (f.state === "deliberate"
          ? 0
          : f.count *
            (f.lens === "stance"
              ? 0.3
              : f.lens === "naming"
                ? 0.4
                : f.lens === "style"
                  ? 0.1
                  : 0)),
      0,
    ),
  );
}
export function ruleValues(
  text: string,
  findings: Finding[],
): Record<string, number> {
  const features = scoreStaticFeatures(text).perFeature;
  return {
    evidence: features.evidence,
    pacing: features.pacing,
    vocabulary: features.vocabulary,
    integrity: features.integrity,
    paragraphShape: features.paragraphShape,
    structure: features.structure,
    consistency: 10 - consistencyPenalty(findings),
  };
}
export function buildScore(
  text: string,
  findings: Finding[],
  confirmation: Confirmation | null,
  edits = 0,
  lastChange: LiveScore["lastChange"] = null,
): LiveScore {
  const values = ruleValues(text, findings);
  const totalWeight = Object.values(RULE_WEIGHTS).reduce((a, b) => a + b, 0);
  const confirmed = confirmation
    ? clampScore(confirmation.review.overallScore / 10)
    : null;
  const ruleCriteria: ScoreCriterion[] = Object.entries(values).map(
    ([key, value]) => ({
      key,
      label: LABELS[key],
      value,
      delta: confirmation ? value - (confirmation.rules[key] ?? value) : 0,
      source: "rule",
      scope: "paragraph",
    }),
  );
  const reviewCriteria: ScoreCriterion[] = Object.values(
    confirmation?.review.judgementGrade?.criteria ?? {},
  ).map((c) => ({
    key: `review:${c.id}`,
    label:
      confirmation?.review.criteria.find((r) => r.id === c.id)?.label ?? c.id,
    value: clampScore(c.score),
    delta: 0,
    source: "review",
    scope: "piece",
  }));
  const estimate =
    text.trim().split(/\s+/).filter(Boolean).length < 150
      ? null
      : clampScore(
          confirmed === null
            ? ruleCriteria.reduce(
                (sum, c) => sum + (c.value * RULE_WEIGHTS[c.key]) / totalWeight,
                0,
              )
            : confirmed +
                ruleCriteria.reduce(
                  (sum, c) =>
                    sum + (c.delta * RULE_WEIGHTS[c.key]) / totalWeight,
                  0,
