export function posAtOffset(block: Block, offset: number, end = false): number {
  const runs = block.runs;
  if (!runs?.length) return block.pos + offset;
  // At a text/atom boundary, starts belong to the next text and ends to the preceding text.
  const run = runs.find(
    (r) =>
      offset >= r.offset &&
      (end ? offset <= r.offset + r.length : offset < r.offset + r.length),
  );
  if (run) return run.pos + offset - run.offset;
  const last = runs[runs.length - 1];
  return last.pos + last.length;
}

export function segmentDocument(doc: PmNode): Segments {
  const blocks: Block[] = [];
  const sections: SectionInfo[] = [];
  let paragraph = 0;
  doc.descendants((node, pos) => {
    if (!node.isTextblock) return;
    const quote = Array.from(
      { length: doc.resolve(pos).depth + 1 },
      (_, i) => doc.resolve(pos).node(i).type.name,
    ).includes("blockquote");
    const kind: Block["kind"] = quote
      ? "quote"
      : node.type.name === "codeBlock"
        ? "code"
        : node.type.name === "heading"
          ? "heading"
          : node.type.name === "paragraph"
            ? "paragraph"
            : "other";
    if (!sections.length || kind === "heading") {
      if (sections.length) sections[sections.length - 1].to = pos;
      sections.push({
        index: sections.length,
        title: kind === "heading" ? node.textContent : "Opening",
        from: pos + 1,
        to: doc.content.size,
        words: 0,
      });
    }
    let text = "";
    const runs: NonNullable<Block["runs"]> = [];
    node.descendants((child, offset) => {
      if (child.isText) {
        runs.push({
          offset: text.length,
          length: child.text!.length,
          pos: pos + 1 + offset,
        });
        text += child.text;
      }
    });
    const section = sections.length - 1;
    if (kind !== "heading") paragraph++;
    blocks.push({
      kind,
      text,
      pos: pos + 1,
      paragraph: Math.max(1, paragraph),
      section,
      runs,
    });
    sections[section].words += text.trim().split(/\s+/).filter(Boolean).length;
    return false;
  });
  return {
    blocks,
    sections,
    plainText: blocks.map((b) => b.text).join("\n\n"),
  };
}

export function occurrence(
  block: Block,
  offset: number,
  length: number,
  id: string,
  extra: Partial<Occurrence> = {},
): Occurrence {
  const contextStart = Math.max(0, offset - 55);
  const contextEnd = Math.min(block.text.length, offset + length + 55);
  let before = block.text.slice(contextStart, offset);
  let after = block.text.slice(offset + length, contextEnd);
  if (contextStart > 0 && /\S/.test(block.text[contextStart - 1]))
    before = before.replace(/^\S*\s/, "");
  if (contextEnd < block.text.length && /\S/.test(block.text[contextEnd]))
    after = after.replace(/\s\S*$/, "");
  return {
    id: `${id}:${posAtOffset(block, offset)}`,
    from: posAtOffset(block, offset),
    to: posAtOffset(block, offset + length, true),
    text: block.text.slice(offset, offset + length),
    before: before.trimStart(),
    after: after.trimEnd(),
    section: block.section,
    paragraph: block.paragraph,
    provenance: "rule",
    flagged: true,
    ...extra,
  };
}

export function finding(
  id: string,
  lens: LensId,
  title: string,
  metric: string,
  occurrences: Occurrence[],
): Finding {
  const count = occurrences.filter((o) => o.flagged).length;
  return {
    id,
    lens,
    title,
    metric,
    level: "piece",
    criterion: "consistency",
    count,
    effort: count,
    impact: null,
    state: count ? "open" : "resolved",
    occurrences: [...occurrences].sort(
      (a, b) => Number(b.flagged) - Number(a.flagged),
    ),
    actions: ["fix-one", "fix-all", "deliberate", "jump"],
    provenance: occurrences.some((o) => o.provenance === "jev")
      ? "jev"
      : "rule",
  };
}

export function matchCase(original: string, replacement: string): string {
  if (/[A-Z]/.test(original) && original === original.toUpperCase())
    return replacement.toUpperCase();
  return /^[A-Z]/.test(original)
    ? replacement[0].toUpperCase() + replacement.slice(1)
    : replacement;
}
import { scoreStaticFeatures } from "../rubric";
import type { RubricResult } from "../../types";
import type {
  Finding,
  LiveScore,
  ScoreCriterion,
} from "../living-desk-contract";

// rubric.ts keeps FEATURE_WEIGHTS private. Mirror its six relevant weights;
// consistency takes the omitted length weight, equal to vocabulary.
export const RULE_WEIGHTS: Record<string, number> = {
  evidence: 0.2,
  pacing: 0.15,
  vocabulary: 0.1,
  integrity: 0.2,
  paragraphShape: 0.1,
  structure: 0.15,
  consistency: 0.1,
};
const LABELS: Record<string, string> = {
  evidence: "Evidence & Support",
  pacing: "Pacing & Rhythm",
  vocabulary: "Vocabulary & Diction",
  integrity: "Bullshit Resistance",
  paragraphShape: "Paragraph Shape",
  structure: "Organization & Flow",
  consistency: "Consistency",
};
export interface Confirmation {
  review: RubricResult;
  at: number;
  rules: Record<string, number>;
}
export const clampScore = (n: number) => Math.max(0, Math.min(10, n));
export function consistencyPenalty(findings: Finding[]): number {
  return Math.min(
    6,
    findings.reduce(
      (sum, f) =>
        sum +
        (f.state === "deliberate"
          ? 0
          : f.count *
            (f.lens === "stance"
              ? 0.3
              : f.lens === "naming"
                ? 0.4
                : f.lens === "style"
                  ? 0.1
                  : 0)),
      0,
    ),
  );
}
export function ruleValues(
  text: string,
  findings: Finding[],
): Record<string, number> {
  const features = scoreStaticFeatures(text).perFeature;
  return {
    evidence: features.evidence,
    pacing: features.pacing,
    vocabulary: features.vocabulary,
    integrity: features.integrity,
    paragraphShape: features.paragraphShape,
    structure: features.structure,
    consistency: 10 - consistencyPenalty(findings),
  };
}
export function buildScore(
  text: string,
  findings: Finding[],
  confirmation: Confirmation | null,
  edits = 0,
  lastChange: LiveScore["lastChange"] = null,
): LiveScore {
  const values = ruleValues(text, findings);
  const totalWeight = Object.values(RULE_WEIGHTS).reduce((a, b) => a + b, 0);
  const confirmed = confirmation
    ? clampScore(confirmation.review.overallScore / 10)
    : null;
  const ruleCriteria: ScoreCriterion[] = Object.entries(values).map(
    ([key, value]) => ({
      key,
      label: LABELS[key],
      value,
      delta: confirmation ? value - (confirmation.rules[key] ?? value) : 0,
      source: "rule",
      scope: "paragraph",
    }),
  );
  const reviewCriteria: ScoreCriterion[] = Object.values(
    confirmation?.review.judgementGrade?.criteria ?? {},
  ).map((c) => ({
    key: `review:${c.id}`,
    label:
      confirmation?.review.criteria.find((r) => r.id === c.id)?.label ?? c.id,
    value: clampScore(c.score),
    delta: 0,
    source: "review",
    scope: "piece",
  }));
  const estimate =
    text.trim().split(/\s+/).filter(Boolean).length < 150
      ? null
      : clampScore(
          confirmed === null
            ? ruleCriteria.reduce(
                (sum, c) => sum + (c.value * RULE_WEIGHTS[c.key]) / totalWeight,
                0,
              )
            : confirmed +
                ruleCriteria.reduce(
                  (sum, c) =>
                    sum + (c.delta * RULE_WEIGHTS[c.key]) / totalWeight,
                  0,
                ),
        );
  return {
    confirmed,
    confirmedAt: confirmation?.at ?? null,
    confirmedLetter: confirmation?.review.overallGrade ?? null,
    estimate,
    editsSinceConfirmed: edits,
    lastChange,
    criteria: [...ruleCriteria, ...reviewCriteria],
  };
}
export function rankFindings(findings: Finding[], estimable = true): Finding[] {
  const penalty = consistencyPenalty(findings);
  const totalWeight = Object.values(RULE_WEIGHTS).reduce((a, b) => a + b, 0);
  const rank = { open: 0, improving: 1, resolved: 2, deliberate: 3 };
  return findings
    .map((f) => ({
      ...f,
      effort: f.count,
      impact:
        f.criterion === "consistency" && estimable && f.state !== "deliberate"
          ? (RULE_WEIGHTS.consistency / totalWeight) *
            (penalty -
              consistencyPenalty(findings.filter((other) => other.id !== f.id)))
          : null,
    }))
    .sort(
      (a, b) =>
        rank[a.state] - rank[b.state] ||
        (a.impact === null ? 1 : 0) - (b.impact === null ? 1 : 0) ||
        (b.impact ?? 0) - (a.impact ?? 0),
    );
}
A ledger tracks one property across the whole document. It always has the same shape:

1. **Code finds every occurrence**, instantly and offline: pronouns outside quotation marks, verb tenses (a local POS tagger such as `compromise` is worth evaluating), capitalised names, spelling variants by edit distance, number and date formats.
2. **Jev classifies only the ambiguous ones**, many per batched request (`passage-triage.ts` already chunks batches against the 64-question cap).
3. **Code totals them and keeps the count live** as the writer edits.
4. **Code offers a fix with a preview**, one occurrence at a time or all at once, plus a **Deliberate** option. Deliberate records the choice as a Charter rule, so the ledger stops nagging and future drift is flagged straight away.

**Stance (I / we) is the clearest case.** A regex can count "we", but it can't tell what the "we" means. For each "we/us/our" outside dialogue, Jev answers one Choice with the sentence before it as context:

- the author alone (editorial or royal we)
- the author and the reader ("as we'll see")
- a group the author belongs to (family, team, town)
- a character speaking
- people in general

Only an editorial "we" mixed with a mostly-"I" piece is a problem. Inclusive and group "we" are normal, and a regex alone would flag them. The fix is mostly deterministic: we→I, us→me, our→my, ourselves→myself, with verb agreement (we are→I am, we were→I was). Harper then checks the result. Each fix moves the count and the Voice criterion.

Other ledgers built the same way:

- **Narrating tense:** one Jev Choice per paragraph (past / present / deliberate shift such as a flashback / unintended mix), ignoring dialogue.
- **Point of view per scene:** whose thoughts we have access to, a Choice over the cast; flags switching heads mid-scene.
- **Naming:** Hollins and Hollis are caught by code alone. Whether *Dr Okafor*, *Ada* and *the doctor* are the same person is a Jev Noul for each candidate pair.
- **Terminology:** "participants", "subjects" and "respondents" drifting for one concept is found by embeddings and confirmed by Jev. A term used before it is defined is caught by code once the definition has been located.
- **Style sheet:** US or UK spelling, serial comma, *ten* or *10*, date formats, hyphenation. Pure code, majority rule, with the exceptions flagged. This is a copyeditor's style sheet the writer gets for free, and it suits Twyne.
- **Who "you" is:** the reader, or anyone in general.
## The living score

Today the rubric asks one Jev Score per criterion of the whole draft (`rubric-grade.ts` `buildRubricQuestions`). It runs after a save, at most once per 30 s, and only for drafts over 500 words. The score therefore cannot say *where* it comes from or move while you edit. `scoreStaticFeatures` is pure code that could run on every keystroke, but it is only called at review time.

**Three cadences:**

| Cadence | What updates | Engine |
| --- | --- | --- |
| Instant | Static features, ledger counts, style sheet, presence grid | Code |
| When a paragraph settles | That paragraph's scores for local criteria (evidence, integrity, pacing, voice); classification of new ledger occurrences | Jev, batched across dirty paragraphs |
| Periodically | Whole-piece criteria (thesis, target fit, structure, promises) | Jev, labelled "read 3 min ago" and marked stale once enough has changed |

**Attribution and honesty.** Paragraph scores show *where the grade comes from*: a heat map per criterion. Code combines them using the composite-scoring pattern (weighted, with a penalty for the weakest paragraph, because readers notice the worst one). The headline grade moves with these estimates, marked ≈, and settles on the confirmed whole-piece reading when it arrives. Paragraph scores averaged together have not been shown to agree with whole-draft judgements; validate that on real drafts before trusting the estimate.

**What matters most.** Every finding, at every level, carries an estimated impact: criterion weight × the distance to the next score level × how much of the piece it covers. It also carries an effort: the number of edits needed. Findings are sorted by impact, so the writer can see what is worth fixing.

**Cards at every level** share one shape:

- `level`: word / sentence / paragraph / section / piece / collection
- `scope`: anchored spans, from 1 up to dozens
- `metric`: a live count or score, with its trend
- `criterion`: which rubric criterion it feeds, used for impact
- `actions`: fix one / review all / make it a rule / open lens / dismiss with reason
- `provenance`: rule, Jev, or text model
- `state`: open / improving / resolved / deliberate

