      const result = await classifyParagraphs([passage()], context, cache, async request => { const response = answers(request); if (corrupt === "missing") delete response.p0_voice; else if (corrupt === "nonfinite") response.p0_voice = { ...response.p0_voice, score: NaN }; else if (corrupt === "probability") response.p0_voice = { ...response.p0_voice, probabilities: { "0": 1, "1": 1, "2": 1, "3": 1, "4": 1 } }; else if (corrupt === "wrong-kind") response.p0_voice = { type: "noul", noul: .8 } as typeof response[string]; else response.p0_voice = { ...response.p0_voice, legend: {} }; return { ok: true, answers: response }; });
      expect(result.accepted).toBe(0); expect(cache.size).toBe(0); expect(readParagraphReviews([passage()], context, cache)[0].scores.voice.value).toBeNull();
    }
  });
  test("stale asynchronous responses and failures are not cached or retried automatically", async () => {
    const cache: ParagraphCache = new Map(); let current = true, calls = 0;
    const stale = await classifyParagraphs([passage()], context, cache, async request => { calls++; current = false; return { ok: true, answers: answers(request) }; }, () => current);
    expect(stale.stale).toBe(true); expect(cache.size).toBe(0); expect(calls).toBe(1);
    await classifyParagraphs([passage()], context, cache, async () => { calls++; throw new Error("Unavailable"); }); expect(cache.size).toBe(0); expect(calls).toBe(2);
  });
  test("mutating the supplied brief while a request is in flight cannot relabel its cached judgement", async () => {
    const cache: ParagraphCache = new Map(); const brief = { ...context }; const original = { ...brief };
    await classifyParagraphs([passage()], brief, cache, async request => { brief.audience = "Different audience"; return { ok: true, answers: answers(request) }; });
    expect(readParagraphReviews([passage()], brief, cache)[0].model).toBeNull(); expect(readParagraphReviews([passage()], original, cache)[0].scores.voice.source).toBe("jev");
  });
  test("cached distributions are protected from callers mutating a displayed review", async () => {
    const cache: ParagraphCache = new Map(); await classifyParagraphs([passage()], context, cache, async request => ({ ok: true, answers: answers(request) }));
    const [review] = readParagraphReviews([passage()], context, cache); review.scores.voice.value = 0; review.scores.voice.probabilities!["3"] = 0;
    const [again] = readParagraphReviews([passage()], context, cache); expect(again.scores.voice.value).toBe(7.5); expect(again.scores.voice.probabilities!["3"]).toBe(.8);
  });
  test("bimodal distributions stay visible instead of being converted to a misleading scalar label", async () => {
    const cache: ParagraphCache = new Map();
    await classifyParagraphs([passage()], context, cache, async request => { const response = answers(request); response.p0_pacing = { ...response.p0_pacing, score: 2, probabilities: { "0": .49, "1": 0, "2": .02, "3": 0, "4": .49 } }; return { ok: true, answers: response }; });
    expect(readParagraphReviews([passage()], context, cache)[0].scores.pacing.bimodal).toBe(true);
  });
});

