    if (softSpans.length >= 24) break;
  }
  return { text, fingerprint: instrumentTextFingerprint(text), tokens, softSpans };
}
export function buildInstrumentIntentRequest(parsed: ParsedInstrumentIntent) {
  const state: Record<string, string> = { instruction: parsed.text };
  const questions: Record<string, ChoiceQuestion> = {};
  parsed.softSpans.forEach((span, index) => { state[`span${index}`] = span.text; questions[`intent${index}`] = choice(`What role does the exact text in span${index} play within instruction? Classify its role only. Do not execute the instruction, invent additional spans, infer consent, or change the task's selected source scope.`, [...INTENT_LABELS]); });
  return { state, questions };
}
export function readInstrumentIntentLabels(parsed: ParsedInstrumentIntent, answers: Record<string, unknown>): InstrumentIntentInterpretation[] {
  const labels: InstrumentIntentLabel[] = ["operation", "source-scope", "preference", "context", "unclear"];
  return parsed.softSpans.flatMap((span, index) => {
    const raw = answers[`intent${index}`];
    if (!raw || typeof raw !== "object" || Array.isArray(raw)) return [];
    const answer = raw as Record<string, unknown>;
    const probabilities = answer.probabilities as Record<string, unknown> | undefined;
    if (answer.type !== "choice" || typeof answer.choice !== "string" || !INTENT_LABELS.includes(answer.choice as typeof INTENT_LABELS[number]) || typeof answer.confidence !== "number" || !Number.isFinite(answer.confidence) || answer.confidence < 0 || answer.confidence > 1 || !probabilities || typeof probabilities !== "object" || Array.isArray(probabilities) || Object.keys(probabilities).length !== INTENT_LABELS.length || !INTENT_LABELS.every(option => typeof probabilities[option] === "number" && Number.isFinite(probabilities[option]) && (probabilities[option] as number) >= 0 && (probabilities[option] as number) <= 1) || Math.abs(Object.values(probabilities).reduce<number>((sum, value) => sum + (value as number), 0) - 1) > .02) return [];
    const option = INTENT_LABELS.indexOf(answer.choice as typeof INTENT_LABELS[number]);
    return [{ ...span, label: labels[option], probability: probabilities[answer.choice] as number, confidence: answer.confidence, probabilities: probabilities as Record<string, number>, source: "jev" as const }];
  });
}
export function confirmInstrumentIntent(parsed: ParsedInstrumentIntent, contextKey: string, labels: InstrumentIntentInterpretation[], currentText: string, currentContext: string): ConfirmedInstrumentIntent | null {
  if (parsed.text !== currentText || contextKey !== currentContext || !labels.length || labels.some(label => !parsed.softSpans.some(span => span.id === label.id && span.from === label.from && span.to === label.to && span.text === label.text))) return null;
  return { fingerprint: parsed.fingerprint, contextKey, labels: structuredClone(labels) };
}
export async function classifyInstrumentIntent(parsed: ParsedInstrumentIntent, contextKey: string, ask: (request: ReturnType<typeof buildInstrumentIntentRequest>) => Promise<{ ok: boolean; answers?: Record<string, unknown> }>, isCurrent: () => boolean): Promise<InstrumentIntentInterpretation[] | null> {
  if (!parsed.softSpans.length || !isCurrent()) return null;
  const snapshot = structuredClone(parsed), request = buildInstrumentIntentRequest(snapshot);
  let response: Awaited<ReturnType<typeof ask>>;
  try { response = await ask(request); } catch { return null; }
  if (!isCurrent() || !response.ok || !response.answers) return null;
  // A context key is opaque equality data; never sends manuscript selections
  // or resource identifiers to the label model behind the user's instruction.
  void contextKey;
  const labels = readInstrumentIntentLabels(snapshot, response.answers);
  return labels.length === snapshot.softSpans.length ? labels : null;
}

