}

/** Engine only. Returns an unregister function. */
export function registerLivingDeskController(
  next: LivingDeskController,
): () => void {
  controller = next;
  return () => {
    if (controller === next) controller = null;
    publishLivingDesk({ ...EMPTY_LIVING_DESK, open: snapshot.open });
  };
}
