              !ui.stale.includes(o.id),
          );
          const canFix = ui.ready && !props.readOnly;
          const context = finding.occurrences.filter((o) => !o.flagged);
          const singular = context.filter(
            (o) =>
              o.label === "singular" || /^(I|me|my|mine|myself)$/i.test(o.text),
          );
          const plural = context.filter((o) => !singular.includes(o));
          const criterion =
            score.criteria.find((c) => c.key === finding.criterion)?.label ??
            finding.criterion;
          return (
            <li
              key={finding.id}
              class={[
                "ld-card",
                `ld-card--${finding.lens}`,
                { "is-open": open, "is-done": done },
              ]}
              data-ld-card={finding.id}
              data-state={finding.state}
            >
              <button
                type="button"
                class="ld-card__head"
                aria-expanded={open}
                disabled={!ui.ready}
                preventdefault:mousedown
                onClick$={() =>
                  controllerFor(!!props.fixture)?.focus(
                    open ? null : finding.id,
                  )
                }
              >
                <span class="ld-card__kicker dept-label">{finding.level}</span>
                <span class="ld-card__impact">
                  {impactLabel(finding, criterion)}
                </span>
                <span class="ld-card__title">
                  {done && <span aria-hidden="true">✓ </span>}
                  {finding.title}
                </span>
                <span class="ld-card__metric">
                  {finding.metric}
                  {snap.judgement === "reading" &&
                    finding.provenance !== "rule" && (
                      <span class="ld-quiet"> · reading…</span>
                    )}
                </span>
              </button>
              {open && (
                <div class="ld-card__body">
                  {!props.readOnly && !done && (
                    <div class="ld-actions">
                      {fixable.length > 1 &&
                        finding.actions.includes("fix-all") && (
                          <button
                            type="button"
                            class="ld-btn ld-btn--primary"
                            disabled={!canFix}
                            preventdefault:mousedown
                            onClick$={() => {
                              controllerFor(!!props.fixture)?.applyAll(
                                finding.id,
                              );
                              void refocusCard(finding.id);
                            }}
      ] as const) {
        const rows = await ctx.db
          .query(table)
          .withIndex("by_userId", (q) => q.eq("userId", userId))
          .take(MAX_ROWS + 1);
        if (rows.length > MAX_ROWS)
          throw new Error("Stored snapshot exceeds row limit");
        for (const row of rows) await ctx.db.delete(table, row._id);
      }
      for (const { id, folioIds, ...c } of args.collections) {
        await ctx.db.insert("houseCollections", {
          userId,
          collectionId: id,
          ...c,
        });
        for (const folioId of folioIds)
          await ctx.db.insert("collectionMembers", {
            userId,
            collectionId: id,
            folioId,
          });
      }
      for (const { id, ...item } of args.charter)
        await ctx.db.insert("charterItems", { userId, itemId: id, ...item });
    }
    for (const { id, ...entry } of args.ledger) {
      const prior = await ctx.db
        .query("contextLedger")
        .withIndex("by_userId_and_entryId", (q) =>
          q.eq("userId", userId).eq("entryId", id),
        )
        .unique();
      if (!prior)
        await ctx.db.insert("contextLedger", { userId, entryId: id, ...entry });
    }
    return null;
  },
});

