    return {
      ok: !batch.remaining,
      remaining: batch.remaining,
      accepted: 0,
      stale: false,
      excludedIds: batch.excludedIds,
    };
  if (!isCurrent())
    return {
      ok: false,
      remaining: true,
      accepted: 0,
      stale: true,
      excludedIds: batch.excludedIds,
    };
