    variants: group.variants,
    mentions: group.mentions,
    counts: segments.sections.map((section) => group.mentions.filter((mention) => mention.section === section.index).length),
  }));
  const evidence: EntityEvidence[] = [];
  let limited = blocks.length < segments.blocks.length || groups.length > candidates.length;
  for (const block of blocks) {
    if (block.kind !== "paragraph" && block.kind !== "quote") continue;
