        if (!evidence.length) continue;
        add({ kind, entityIds: [selectedId, other.id], evidenceIds: evidence.map((span) => span.id), options: [...RELATIONSHIP_OPTIONS] }, evidence.map((span) => span.text), `What relationship is established between ${JSON.stringify(selected.name)} and ${JSON.stringify(other.name)} in this section? Same-paragraph presence alone establishes no relationship. Choose unknown if multiple types or insufficient context.`);
      }
    }
  } else if (kind === "continuity") {
    state.attribute = attribute.trim();
    for (let at = 1; at < passages.length; at++) {
      const evidence = [passages[at - 1], passages[at]];
