    }
  } else {
    const speakers = index.candidates.slice(0, 8);
    if (!speakers.some((candidate) => candidate.id === selectedId)) speakers[speakers.length - 1] = selected;
    state.speakers = JSON.stringify(speakers.map((speaker) => speaker.name));
    for (const span of index.evidence.filter((span) => span.kind === "dialogue" && span.entityIds.includes(selectedId))) {
