      add({ kind, entityIds: speakers.map((speaker) => speaker.id), evidenceIds: [span.id], options: [...speakers.map((speaker) => speaker.name), UNKNOWN_SPEAKER] }, [span.text], "Blind voice test: choose a speaker using only the utterance and brief. Attribution tags and neighbouring narration are deliberately absent. Choose unknown or indistinguishable if the voices are not distinguishable; this is not a correctness or voice-quality score.");
    }
  }
  const key = JSON.stringify([index.key, selectedId, kind, contextKey, context, attribute, specs, state]);
  return { key, indexKey: index.key, contextKey, state, questions, specs, excluded };
}

/** Strict response projection: question IDs/evidence/offsets always come from code. */
export function readEntityInstrumentResponse(request: EntityInstrumentRequest, response: { ok: boolean; model?: string; answers?: Record<string, unknown> }, at = Date.now()): EntityInstrumentResult | null {
  if (!response.ok || !response.answers || !request.specs.length) return null;
