/**
 * Utility function for rendering content with a main line prefix and nested indented content.
 *
 * This function handles the common pattern of rendering content with:
 * 1. A main line with a prefix (like "- " for lists, "> " for blockquotes, etc.)
 * 2. Nested content that gets indented properly
 *
 * @param node - The ProseMirror node representing the content
 * @param h - The markdown renderer helper
 * @param prefixOrGenerator - Either a string prefix or a function that generates the prefix from context
 * @param ctx - Optional context object (used when prefixOrGenerator is a function)
 * @returns The rendered markdown string
 *
 * @example
 * ```ts
 * // For a bullet list item with static prefix
 * return renderNestedMarkdownContent(node, h, '- ')
 *
 * // For a task item with static prefix
 * const prefix = `- [${node.attrs?.checked ? 'x' : ' '}] `
 * return renderNestedMarkdownContent(node, h, prefix)
 *
 * // For a blockquote with static prefix
 * return renderNestedMarkdownContent(node, h, '> ')
 *
 * // For content with dynamic prefix based on context
 * return renderNestedMarkdownContent(node, h, ctx => {
 *   if (ctx.parentType === 'orderedList') {
 *     return `${ctx.index + 1}. `
 *   }
 *   return '- '
 * }, ctx)
 *
 * // Custom extension example
 * const CustomContainer = Node.create({
 *   name: 'customContainer',
 *   // ... other config
 *   markdown: {
 *     render: (node, h) => {
 *       const type = node.attrs?.type || 'info'
 *       return renderNestedMarkdownContent(node, h, `[${type}] `)
 *     }
 *   }
 * })
 * ```
 */
export function renderNestedMarkdownContent(
  node: JSONContent,
  h: {
    renderChildren: (nodes: JSONContent[]) => string
    renderChild?: (node: JSONContent, index: number) => string
    indent: (text: string) => string
  },
  prefixOrGenerator: string | ((ctx: any) => string),
  ctx?: any,
): string {
  if (!node || !Array.isArray(node.content)) {
    return ''
  }

  // Determine the prefix based on the input
  const prefix = typeof prefixOrGenerator === 'function' ? prefixOrGenerator(ctx) : prefixOrGenerator

  const [content, ...children] = node.content

  // Render the main content (typically a paragraph)
  const mainContent = h.renderChildren([content])
  let output = `${prefix}${mainContent}`

  // Handle nested children with proper indentation
  if (children && children.length > 0) {
    children.forEach((child, index) => {
      const childContent = h.renderChild?.(child, index + 1) ?? h.renderChildren([child])
      if (childContent !== undefined && childContent !== null) {
        // Split the child content by lines and indent each line
        const indentedChild = childContent
          .split('\n')
          .map(line => (line ? h.indent(line) : h.indent('')))
          .join('\n')

        output += child.type === 'paragraph' ? `\n\n${indentedChild}` : `\n${indentedChild}`
      }
    })
  }

  return output
}
","import type { Editor } from '../Editor.js'

/**
 * Per-editor registry for centralized NodeView position-change checks.
 * A single editor.on('update') listener + rAF is shared across all NodeViews
 * for a given editor, keeping overhead bounded regardless of NodeView count.
 *
 * This is consumed by React, Vue 3, and Vue 2 NodeView renderers.
 */
interface PositionUpdateRegistry {
  callbacks: Set<() => void>
  rafId: number | null
  handler: () => void
}

const positionUpdateRegistries = new WeakMap<Editor, PositionUpdateRegistry>()

/**
 * Register a callback to be called (via a shared rAF) after every editor
 * update transaction. If this is the first registration for the given editor,
 * a new registry entry and a single `editor.on('update')` listener are created.
 */
export function schedulePositionCheck(editor: Editor, callback: () => void): void {
  let registry = positionUpdateRegistries.get(editor)

  if (!registry) {
    const newRegistry: PositionUpdateRegistry = {
      callbacks: new Set(),
      rafId: null,
      handler: () => {
        if (newRegistry.rafId !== null) {
          cancelAnimationFrame(newRegistry.rafId)
        }
        newRegistry.rafId = requestAnimationFrame(() => {
          newRegistry.rafId = null
          newRegistry.callbacks.forEach(cb => cb())
        })
      },
    }

    positionUpdateRegistries.set(editor, newRegistry)
    editor.on('update', newRegistry.handler)
    registry = newRegistry
  }

  registry.callbacks.add(callback)
}

/**
 * Unregister a previously registered callback. When the last callback for an
 * editor is removed, the shared listener and any pending rAF are also cleaned up.
 */
export function cancelPositionCheck(editor: Editor, callback: () => void): void {
  const registry = positionUpdateRegistries.get(editor)

  if (!registry) {
    return
  }

  registry.callbacks.delete(callback)

  if (registry.callbacks.size === 0) {
    if (registry.rafId !== null) {
      cancelAnimationFrame(registry.rafId)
    }

    editor.off('update', registry.handler)
    positionUpdateRegistries.delete(editor)
  }
}
