  (originRange, targetPos) =>
  ({ editor, tr }) => {
    const { state } = editor

    const contentSlice = state.doc.slice(originRange.from, originRange.to)

    tr.deleteRange(originRange.from, originRange.to)
    const newPos = tr.mapping.map(targetPos)

