  // Default: check if we can insert at the current position
  let depth = $from.depth

  while (depth >= 0) {
    const index = $from.index(depth)
    const parent = $from.node(depth)
    const match = parent.contentMatchAt(index)
    if (match.matchType(nodeType)) {
      return true
    }
    depth -= 1
  }
  return false
}
