/** Instruments keep a source snapshot after the ordinary selection closes. */
const askInstrumentRoom = $(async (
  request: InstrumentRoomRequest,
  anchor: InstrumentRoomAnchor,
): Promise<InstrumentRoomResult> => {
  const editor = store.editor;
  const account = auth.value.user?.id ?? null;
  const fresh = () => !!editor && !editor.isDestroyed && editor.isEditable &&
    !readOnly && store.editor === editor &&
    (auth.value.user?.id ?? null) === account &&
    instrumentRoomAnchorMatches(editor.state.doc, store.activeFolioId ?? "", anchor);
  if (!fresh() || !request.body.trim() || request.body.length > 24_000)
    return { ok: false, message: "The source changed. Reopen the instrument before inviting an editor." };
  const { loadPersonasFromIdb } = await import("../../utils/idb");
  const { PERSONAS } = await import("../../utils/personas");
  const cast = await loadPersonasFromIdb();
  const persona = (cast?.length ? cast : PERSONAS).find((item) => item.id === request.personaId);
  if (!fresh() || !persona || persona.name !== request.personaName)
    return { ok: false, message: "The room or source changed. Invite an editor again." };
  // The request quotes tool context. Any @name inside that evidence is data,
  // not another invitation through the ordinary mention dispatcher.
  const commentId = await createSelectionComment(request.body, anchor, true, false);
  if (!commentId) return { ok: false, message: "The margin request could not be saved." };
  if (!fresh()) return { ok: false, message: "The question was saved with its earlier passage. No editor was called after the context changed." };
  store.selectionAction = null;
  await onEditorialContext$?.("comments");
  if (!fresh()) return { ok: false, message: "The question was saved. Reopen its margin thread to invite an editor." };
  window.dispatchEvent(new CustomEvent("twyne:ask-persona-on-comment", {
    detail: { commentId, personaId: persona.id },
  }));
  return { ok: true, message: `The request for ${persona.name} is saved in the margin.` };
});

return (
  <div ref={editorRoot} class="flex h-full flex-1 flex-col min-h-0">
    {readOnly && (
      <div
        class="border-b border-[var(--color-paper-3)] bg-[var(--color-paper-soft)] px-4 py-2 text-xs text-[var(--color-ink-light)]"
        role="status"
      >
        Commenter access. You can read and discuss this folio, but only its
        owner and editors can change the manuscript.
      </div>
    )}
    <TypstWorkspace
      store={store}
      editor={store.editor ? noSerialize(store.editor) : undefined}
      readOnly={readOnly}
      folioName={activeFolio?.name ?? "Untitled"}
      brief={brief}
    >
      <div
        q:slot="compositor"
        class="editor-writing-compositor"
        hidden={store.typstView !== "write"}
