test("A delayed judgement for changed source is dropped before a fresh source gets its own reply", async ({ page }, info) => {
  let release!: () => void;
  const held = new Promise<void>((resolve) => { release = resolve; });
  const transport = await installRoomTransports(page, { holdJudgement: held });
  try {
    await seedRoom(page);
    const original = await draftRoomText(page);
    const invitation = await openSentence(page);
    await invitation.getByRole("button", { name: "Ask the room", exact: true }).click();
    await expect.poll(() => transport.judgements.length).toBe(1);
    await selectRoomPassage(page, INSTRUMENT_SENTENCE);
    await page.keyboard.insertText(CHANGED_SENTENCE);
    await expect(manuscript(page).locator("strong").first()).toHaveText(CHANGED_SENTENCE);
    const finished = page.waitForResponse((response) => response.url() === `${JUDGEMENT_ENDPOINT}/v1/systemone` && response.request().method() === "POST");
    release();
    await (await finished).finished();
    const current = await openSentence(page, CHANGED_SENTENCE);
    await current.getByRole("button", { name: "Ask the room", exact: true }).click();
    const { saved, masthead } = await assertSavedReply(page, CHANGED_SENTENCE);
    expect(transport.judgements).toHaveLength(2);
    expect(transport.judgements.map((request) => request.state.source)).toEqual([INSTRUMENT_SENTENCE, CHANGED_SENTENCE]);
    expect(transport.replies).toHaveLength(1);
    expect(saved.text).toContain(CHANGED_SENTENCE);
    expect(saved.text).not.toContain(INSTRUMENT_SENTENCE);
    await assertKnownPortrait(masthead);
    expect(await draftRoomText(page)).toBe(original!.replace(INSTRUMENT_SENTENCE, CHANGED_SENTENCE));
    await attachMission(page, info, "old-source-dropped-new-source-replied");
  } finally { release(); }
});

