  await expect(invitation.getByRole("button", { name: "Ask the room", exact: true })).toBeEnabled();
  return invitation;
}
async function inspectInvitation(invitation: Locator, source: string, proposal?: string) {
  await invitation.locator("summary").filter({ hasText: /^Inspect this invitation$/ }).click();
  const quoted = invitation.locator("blockquote");
  await expect(quoted.first()).toHaveText(source);
  if (proposal !== undefined) await expect(quoted.nth(1)).toHaveText(proposal);
}
async function assertSavedReply(
  page: Page,
  anchor: string,
  persona = KNOWN_EDITOR,
) {
  await expect.poll(async () =>
    (await savedRoomComments(page)).map((comment) => ({
      folioId: comment.folioId,
      anchor: comment.anchor,
      replies: comment.replies.map((reply) => ({ personaId: reply.personaId, author: reply.author, text: reply.text })),
    })),
  ).toEqual([{
    folioId: FOLIO_ID,
    anchor,
    replies: [{ personaId: persona.id, author: persona.name, text: FIXTURE_REPLY }],
  }]);
  const [saved] = await savedRoomComments(page);
  const reply = page.locator(`[data-speech-id="comment-reply-${saved.replies[0].id}"]:visible`).first();
  await expect(reply).toHaveText(FIXTURE_REPLY);
  const thread = page.locator(`[data-comment-id="${saved.id}"]:visible`)
    .filter({ has: page.locator(`[data-speech-id="comment-reply-${saved.replies[0].id}"]`) }).first();
  const masthead = thread.locator(".persona-masthead").filter({ hasText: persona.name }).first();
  await expect(masthead.locator(".persona-masthead__name")).toHaveText(persona.name);
  await expect(masthead.locator(".persona-masthead__role")).toHaveText(persona.role);
  const headBox = await masthead.boundingBox(), replyBox = await reply.boundingBox();
  expect(headBox).not.toBeNull();
  expect(replyBox).not.toBeNull();
  expect(headBox!.y + headBox!.height).toBeLessThanOrEqual(replyBox!.y + 1);
  return { saved, masthead };
}
async function assertKnownPortrait(masthead: Locator) {
  const portrait = masthead.locator('[data-persona-portrait="editor"]');
  await expect(portrait).toHaveCount(1);
  await expect(portrait.locator("img")).toHaveAttribute("src", "/assets/manual/editors/editor-transparent-480.webp");
  await expect.poll(() => portrait.locator("img").evaluate((image) =>
    (image as HTMLImageElement).complete && (image as HTMLImageElement).naturalWidth > 0,
  )).toBe(true);
}
async function attachMission(page: Page, info: TestInfo, name: string) {
  info.annotations.push({ type: "proof-boundary", description: "Real application UI/persistence with labelled network fixtures; no live Jev, prose provider or signed-in account proof." });
  const path = info.outputPath(`${name}.png`);
  await page.screenshot({ path, animations: "disabled" });
  await info.attach(name, { path, contentType: "image/png" });
}

