import zipfile,json
from pathlib import Path
for p in Path('artifacts/qa-recordings/instruments-release/editorial-room/results').glob('*/trace.zip'):
 print(p.parent.name)
 with zipfile.ZipFile(p) as z:
  for line in z.read('0-trace.network').decode().splitlines():
   e=json.loads(line)
   req=e.get('snapshot',{}).get('request',{})
   if '/api/provider/' not in req.get('url',''):continue
   data=req.get('postData',{})
   body=data.get('text','')
   if not body and data.get('_sha1') in z.namelist():body=z.read(data['_sha1']).decode()
   if not body and 'resources/'+str(data.get('_sha1')) in z.namelist():body=z.read('resources/'+data['_sha1']).decode()
   try:v=json.loads(body)
   except: print('No captured body',list(data));continue
   print('model',v.get('model'),'stream',v.get('stream'))
   for msg in v.get('messages',[]):print(msg.get('role'),str(msg.get('content'))[:1400])
