      page.evaluate(
        () => document.documentElement.scrollWidth <= window.innerWidth + 1,
      ),
    )
    .toBe(true);
  expect(await draftRoomText(page)).toBe(original);
  await attachMission(page, info, "narrow-custom-editor-honest-identity");
});

